const colors={Primary:'#168078',Secondary:'#d39a31',Tertiary:'#6654a4',Unclassified:'#80909c'};
const labels={photo:'Phototherapy',cpap:'CPAP respiratory support',power:'Electricity',solar:'Solar backup',water:'Running water',surgery:'Paediatric surgery (mission)',neonatal:'Tertiary neonatal care'};
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let facilities=[],visible=[],selected=null,level='All',markers=new Map();
const map=L.map('map',{zoomControl:false,zoomSnap:0.25}).setView([13.48,-15.35],8);L.control.zoom({position:'topright'}).addTo(map);L.control.scale({imperial:false,position:'bottomright'}).addTo(map);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',subdomains:'abcd',maxZoom:19}).addTo(map);
const group=L.layerGroup().addTo(map);
function careLevel(f){return f[$('classification').value==='neonatal'?'neonatalLevel':'generalLevel']}
function classificationName(){return $('classification').value==='neonatal'?'Neonatal':'General'}
function classificationChanged(){level='All';$('search').value='';$('resource').value='';$('status').value='yes';$('status').disabled=true;closeDetail();drawLevels();render();fit();}
$('classification').onchange=classificationChanged;
function matching(f){return($('classification').value!=='neonatal'||f.assessed)&&(level==='All'||careLevel(f)===level)&&($('coverage').value!=='assessed'||f.assessed)&&(! $('search').value.trim()||`${f.name} ${f.aliases} ${f.region}`.toLowerCase().includes($('search').value.trim().toLowerCase()))&&(!$('resource').value||(f.resources[$('resource').value]||'unknown')===$('status').value)}
function render(){visible=facilities.filter(matching);group.clearLayers();markers.clear();$('count').textContent=`${visible.length} facilit${visible.length===1?'y':'ies'}`;$('mapstats').textContent=$('classification').value==='neonatal'?`Neonatal assessment · ${visible.length} of 15 facilities shown`:`General care levels · ${visible.length} facilities shown`;
$('results').innerHTML=visible.length?visible.map(f=>`<button class="facility${selected===f.id?' selected':''}" data-id="${esc(f.id)}"><strong>${esc(f.name)}</strong><small><span class="dot" style="background:${colors[careLevel(f)]}"></span>${esc(careLevel(f))} ${classificationName().toLowerCase()} · ${esc(f.region)}${f.assessed?'<span class="assessed">ASSESSED</span>':''}</small></button>`).join(''):'<div class="empty">No facilities match these filters. Try another provision status or reset the filters.</div>';
visible.forEach(f=>{let m=L.circleMarker([f.lat,f.lng],{radius:7,color:'white',weight:1.8,fillColor:colors[careLevel(f)],fillOpacity:.92}).addTo(group).bindTooltip(esc(f.name),{direction:'top'}).on('click',()=>select(f.id));markers.set(f.id,m)});
if(selected&&!visible.some(f=>f.id===selected))closeDetail();else if(selected)highlight();
}
function highlight(){markers.forEach((m,id)=>m.setStyle({radius:7,weight:id===selected?3:1.8,color:id===selected?'#193e42':'white'}))}
function select(id){let f=facilities.find(f=>f.id===id);selected=id;map.setView([f.lat,f.lng],Math.max(map.getZoom(),11));$('detail').hidden=false;$('detail').innerHTML=`<button class="close" id="closeDetail" aria-label="Close facility details">×</button><div class="eyebrow">FACILITY PROFILE</div><h2>${esc(f.name)}</h2><span class="badge">General: ${esc(f.generalLevel)}</span> <span class="badge">Neonatal: ${esc(f.neonatalLevel)}</span><p>${esc(f.region)} · ${esc(f.ownership)}<br>${esc(f.type)}<br><b>General classification evidence:</b> ${esc(f.generalLevelEvidence)}<br><b>General level:</b> ${esc(f.generalLevelBasis)}<br><b>Neonatal level:</b> ${esc(f.neonatalLevelBasis)}</p><div class="eyebrow">REPORTED SERVICES & RESOURCES</div>${Object.entries(labels).map(([k,label])=>{const v=f.resources[k]||'unknown';return `<div class="resourceRow"><span>${label}</span><strong class="${v}">${v==='yes'?(k==='photo'?'Some · insufficient':'Available'):v==='no'?'Unavailable':'Not documented'}</strong></div>`}).join('')}<p>${f.assessed?'Assessment: PATG workshop, 12–13 November 2025. Electricity/water may be intermittent despite “Yes” responses. CPAP: structured table used; conflicting unattributed workshop comments remain unresolved.':'No facility-level neonatal resource assessment in the supplied reports.'}${f.resources.surgery?' Paediatric surgery: November 2025 HF mission activity; ongoing availability unconfirmed.':''}</p><p><b>${f.approx?'Approximate locality position':'Source coordinates'}</b><br>${f.lat.toFixed(5)}, ${f.lng.toFixed(5)}<br>${esc(f.locationSource)}</p><a href="${esc(f.locationUrl)}" target="_blank" rel="noopener">View location source ↗</a><p>Recorded name: ${esc(f.aliases)}</p>`;$('closeDetail').onclick=closeDetail;document.querySelectorAll('.facility').forEach(b=>b.classList.toggle('selected',b.dataset.id===id));highlight()}
function closeDetail(){selected=null;$('detail').hidden=true;document.querySelectorAll('.facility').forEach(b=>b.classList.remove('selected'));highlight()}
function fit(){if(visible.length)map.fitBounds(L.latLngBounds(visible.map(f=>[f.lat,f.lng])),{padding:[35,100],maxZoom:13})}
$('results').onclick=e=>{let b=e.target.closest('[data-id]');if(b)select(b.dataset.id)};
['search','coverage','status'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));$('resource').onchange=()=>{$('status').disabled=!$('resource').value;render()};
function drawLevels(){const neonatal=$('classification').value==='neonatal';if($('coverage').dataset.context!==$('classification').value){$('coverage').innerHTML=neonatal?'<option value="assessed">All 15 neonatal assessment facilities</option>':'<option value="all">All mapped facilities</option><option value="assessed">November 2025 assessed facilities</option>';$('coverage').disabled=neonatal;$('coverage').dataset.context=$('classification').value;}$('levelLabel').textContent=classificationName()+' level of care';$('legendTitle').textContent=classificationName()+' care';$('levelHint').textContent=$('classification').value==='neonatal'?'All 15 facilities in the neonatal assessment. Levels clarified for seven; eight remain unclassified.':'Uses the intended structure in strategic plan §4.1. Historical type-based assignments are provisional; §2.7 differs on minor centres. See Data & sources.';$('levels').innerHTML=['All',...Object.keys(colors)].map(l=>`<button data-level="${l}" aria-pressed="${l===level}" class="${l===level?'active':''}">${l}</button>`).join('')}
$('levels').onclick=e=>{if(e.target.dataset.level){level=e.target.dataset.level;drawLevels();render()}};
$('reset').onclick=()=>{level='All';closeDetail();$('search').value='';$('coverage').value=$('classification').value==='neonatal'?'assessed':'all';$('resource').value='';$('status').value='yes';$('status').disabled=true;drawLevels();render();fit()};$('fit').onclick=fit;
$('sourcesButton').onclick=()=>$('sources').showModal();$('closeSources').onclick=()=>$('sources').close();$('sources').onclick=e=>{if(e.target===$('sources')){const r=$('sources').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('sources').close()}};
$('export').onclick=()=>{const headers=['Facility','General care level','Neonatal care level','Facility type','Region','Ownership','Latitude','Longitude','Approximate location','Assessment Nov 2025',...Object.values(labels),'Location source','General level basis','General classification evidence','General classification source','Neonatal level basis'];const quote=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';const csv=[headers,...visible.map(f=>[f.name,f.generalLevel,f.neonatalLevel,f.type,f.region,f.ownership,f.lat,f.lng,f.approx,f.assessed,...Object.keys(labels).map(k=>f.resources[k]||'unknown'),f.locationSource,f.generalLevelBasis,f.generalLevelEvidence,f.generalLevelSource,f.neonatalLevelBasis])].map(r=>r.map(quote).join(',')).join('\r\n');let u=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='gambia-health-facilities.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
async function init(){try{const r=await fetch('facilities.json');if(!r.ok)throw Error('Facility data failed to load');facilities=await r.json();$('coverageNote').textContent=`${facilities.length} facilities: 101 historical public-sector database records plus Ahmadiyya and Njau from the supplied assessment. All 15 assessed facilities are included. Private, new, renamed, closed and unmapped facilities may be missing. Only 15 have structured resource data; other services remain undocumented. Njau is placed at an approximate village location. Neonatal levels and general health-system levels are recorded separately. The neonatal view contains exactly the 15 assessment facilities, including eight with unclassified neonatal levels. The general-services view contains the wider 103-facility dataset. Neonatal levels are confirmed for seven facilities only. Switch the classification selector to compare the two contexts.`;drawLevels();render();fit();const b=await fetch('gambia-boundary.json');if(b.ok)L.geoJSON(await b.json(),{interactive:false,style:{color:'#408479',weight:1.6,fillColor:'#70ad8b',fillOpacity:.06}}).addTo(map).bringToBack()}catch(e){$('results').textContent='Unable to load facility data. Please reload the page.';console.error(e)}}init();
